def release_interrupted_claim(claim, state, deps, detail):
    """Undo a dispatch that failed after claim creation.

    A claim is a fence, not durable work state. If dispatch bookkeeping fails
    before the lap is durably recorded, leave neither the fence nor a child
    process behind; otherwise the next tick can never select the issue again.
    """
    lap = state.get("lap")
    killer = deps.get("kill_lap")
    if lap and lap.get("pid") and killer:
        try:
            killer(lap)
        except Exception:
            pass
    path = claim.get("path")
    if path:
        try:
            os.remove(path)
        except OSError:
            pass
    state["lap"] = None
    try:
        runtime_log("intervention", issue=claim.get("issue"),
                    detail="%s; released claim %s" % (detail, path))
    except Exception:
        pass


def dispatch(state, now, deps):
    """Start at most one lap. Returns disposition string."""
    if state.get("lap"):
        return "already-running"
    claim = deps["claim"](now)
    if not claim:
        return "idle"
    try:
        # L-013: never spend a lap on an already-satisfied issue. Re-prove the
        # repro is RED on fresh main first; GREEN → reconcile as merged + skip.
        recheck = deps.get("red_recheck")
        if recheck:
            verdict = recheck(claim["issue"])
            runtime_log("red-recheck", issue=claim["issue"], verdict=verdict)
            if verdict == "pass":
                state.setdefault("issues", {}).setdefault(str(claim["issue"]), {"retries": 0})
                state["issues"][str(claim["issue"])] ["disposition"] = "merged"
                try:
                    os.remove(claim["path"])
                except OSError:
                    pass
                save_state(state, deps["state_path"])
                return "already-satisfied"
        state["lap"] = {
            "issue": claim["issue"],
            "claim_path": claim["path"],
            "started_at": now,
            "pid": None,
        }
        # wallclock guard measures the current lap session, not all history:
        # refresh so a supervisor restarted hours later dispatches instead of HALT
        state["started_at"] = now
        deps["start_lap"](claim["issue"], state["lap"])
        runtime_log("dispatch", issue=claim["issue"], pid=state["lap"].get("pid"))
        save_state(state, deps["state_path"])
        return "dispatched"
    except Exception as error:
        release_interrupted_claim(
            claim, state, deps, "dispatch failed: %s: %s" % (type(error).__name__, error))
        raise


